use crate::events::{now_unix_ms,EventKind,EventSource,MarketEvent};
use futures_util::{SinkExt,StreamExt}; use serde_json::{json,Value}; use thiserror::Error; use tokio::time::{sleep,Duration}; use tokio_tungstenite::{connect_async,tungstenite::Message}; use tracing::{error,info,warn};
#[derive(Debug,Error)] pub enum PumpPortalError{#[error("websocket connection failed: {0}")]Connect(#[from]tokio_tungstenite::tungstenite::Error),#[error("subscription serialization failed: {0}")]Serialize(#[from]serde_json::Error)}
pub fn parse_event(value:&Value)->Option<MarketEvent>{let mint=value.get("mint").and_then(Value::as_str).map(str::to_owned);let tx=value.get("txType").and_then(Value::as_str).unwrap_or_default();let kind=match tx{"create"=>EventKind::TokenCreated,"buy"|"sell"=>EventKind::Trade,_=>return None};Some(MarketEvent{event_id:format!("pumpportal-{}-{}",now_unix_ms(),mint.as_deref().unwrap_or("unknown")),observed_at_unix_ms:now_unix_ms(),slot:value.get("slot").and_then(Value::as_u64),signature:value.get("signature").and_then(Value::as_str).map(str::to_owned),mint,symbol:value.get("symbol").and_then(Value::as_str).map(str::to_owned),source:EventSource::PumpFun,kind,sol_amount:value.get("solAmount").and_then(Value::as_f64),token_amount:value.get("tokenAmount").and_then(Value::as_f64),is_buy:match tx{"buy"=>Some(true),"sell"=>Some(false),_=>None},trader:value.get("traderPublicKey").and_then(Value::as_str).map(str::to_owned)})}
